package Tv5.Controller;
import Tv5.View.ChiThuPage;import MainPage.View.Workspace;import MainPage.Controller.PageTasks;import MainPage.Controller.MainPageController;import Model.*;import Service.*;import java.util.*;import java.time.*;import java.math.*;import javax.swing.*;
public class ChiThuController {
 private final ChiThuPage v;private final int b;private List<GiaoDichTaiChinhModel> data=List.of();private final JComboBox<String> period;private final JTextField year,number;
 public ChiThuController(ChiThuPage v,int b){this(v,b,"Cơ sở #"+b);}
 public ChiThuController(ChiThuPage v,int b,String name){this.v=v;this.b=b;v.title("CHI THU — "+name,"Giao dịch và tổng hợp dòng tiền thực thu/chi");v.columns("Mã","Ngày","Loại","Học viên","Số tiền","Trạng thái","Hạn thanh toán","Diễn giải");period=v.comboFilter("Tháng","Quý","Năm","Tất cả");year=v.textFilter("Năm",""+LocalDate.now().getYear(),5);number=v.textFilter("Tháng/quý",""+LocalDate.now().getMonthValue(),3);v.action("Lọc",this::render);v.action("Tải lại",()->load(true));v.action("Chi tiết",()->{int i=v.selected();if(i>=0)Workspace.message(v,"Giao dịch #"+v.value(i,0)+"\n"+v.value(i,7));});load(false);}
 private void load(boolean refresh){v.status("Đang tải...");PageTasks.run(v,()->{var s=new GiaoDichTaiChinhService();var list=refresh?s.reload(b):s.selectAll(b);try{MainPageController.setBadgeCount(b,"CHI_THU","GiaoDichNhap",(int)list.stream().filter(x->"NHAP".equals(x.getTrangThai())).count());}catch(java.io.IOException ignored){}return list;},r->{data=r;render();});}
 private void render(){try{int p=period.getSelectedIndex(),y=p==3?0:Integer.parseInt(year.getText().trim()),n=p>=2?0:Integer.parseInt(number.getText().trim());PageTasks.require(p>=2||n>=1&&n<=(p==0?12:4),"Tháng/quý không hợp lệ");BigDecimal thu=BigDecimal.ZERO,chi=BigDecimal.ZERO,hoan=BigDecimal.ZERO;List<Object[]> rows=new ArrayList<>();for(var x:data){if(x.getNgayGiaoDich()==null)continue;LocalDate d=x.getNgayGiaoDich().toLocalDate();if(p!=3&&(d.getYear()!=y||p==0&&d.getMonthValue()!=n||p==1&&(d.getMonthValue()-1)/3+1!=n))continue;rows.add(new Object[]{x.getMaGiaoDich(),x.getNgayGiaoDich(),x.getLoaiGiaoDich(),x.getMaHocVien(),x.getSoTien(),x.getTrangThai(),x.getHanThanhToan(),x.getDienGiai()});if(!"XAC_NHAN".equals(x.getTrangThai())||x.getSoTien()==null)continue;switch(x.getLoaiGiaoDich()){case "THU"->thu=thu.add(x.getSoTien());case "CHI"->chi=chi.add(x.getSoTien());case "HOAN"->hoan=hoan.add(x.getSoTien());}}v.rows(rows.toArray(Object[][]::new));v.status("Thu: "+thu.toPlainString()+" | Chi: "+chi.toPlainString()+" | Hoàn: "+hoan.toPlainString()+" | Dòng tiền ròng: "+thu.subtract(chi).subtract(hoan).toPlainString()+" | "+rows.size()+" giao dịch");}catch(Exception e){Workspace.message(v,e.getMessage());}}
}
